diff --git a/AGENTS.md b/AGENTS.md
index b16888ab8..80f1c6ccd 100644
--- a/AGENTS.md
+++ b/AGENTS.md
@@ -19,7 +19,7 @@ Rules for AI agents working in this repo.

 - Full pipeline: `just ci` (includes the 90% coverage gate). `just test`, `just lint`, `just fmt`.
 - Before every push or PR: `just pre-push && just lint && just doc-check && just test`, and `just ci` before marking a PR ready. Judge each by its exit code. Never tail or grep the output for success (a compile error prints no "failed" line), and never report a check as passed that was not run.
-- Recovery evidence: `just verify-real` rehearses partial publish, delayed visibility, a conflicting tag and a missing Python artifact against local npm and PyPI registries bound over self-signed `https://` through `[registries]`. It installs its tools under `target/verify-real` and is not part of `just ci`. A local Cargo registry cannot be bound: callisto always publishes with `--registry crates-io`.
+- Recovery evidence: `just verify-real` rehearses partial publish, delayed visibility, a conflicting tag and a missing Python artifact against local npm, PyPI and Cargo registries through the production registry binding, then runs the native install matrix. It installs its tools under `target/verify-real` (npm, pnpm and uv must already be on PATH) and is not part of `just ci`.
 - Commits must be signed: the ruleset requires it. Never pass `-c commit.gpgsign=false`. After pushing, `gh api repos/orin-dx/callisto/commits/<sha> --jq .commit.verification.reason` must say `valid`.
 - Performance: `just bench` times `status`, `version --dry-run` and `release --dry-run` over generated workspaces and counts the git processes each starts (`CALLISTO_BENCH_SHAPES=1` lists which). A change that adds a git process per package fails review.
 - Scoped iteration: one `cargo test -p <crate>` or `cargo clippy -p <crate> --all-targets -- -D warnings` at a time.
diff --git a/crates/callisto-cli/tests/common/local_registries.rs b/crates/callisto-cli/tests/common/local_registries.rs
index e7eea8b6d..a306f70c9 100644
--- a/crates/callisto-cli/tests/common/local_registries.rs
+++ b/crates/callisto-cli/tests/common/local_registries.rs
@@ -308,6 +308,110 @@ pub fn start_json_simple_index(external: &Path, name: &str, port: u16, packages_
     guard
 }

+/// A Cargo sparse registry with the publish and download API, persisted under its directory so a restart keeps what was
+/// published. `refuse_after` publishes succeed, then every publish fails; `index_delay` seconds pass between a publish and
+/// the index showing it. Requests are logged to stderr.
+const SPARSE_CARGO_REGISTRY: &str = r#"
+import hashlib, http.server, json, os, re, sys, threading, time
+root, port, refuse_after, index_delay = sys.argv[1], int(sys.argv[2]), int(sys.argv[3]), float(sys.argv[4])
+state_path = os.path.join(root, "state.json")
+os.makedirs(os.path.join(root, "crates"), exist_ok=True)
+lock = threading.Lock()
+state = json.load(open(state_path)) if os.path.exists(state_path) else {"entries": []}
+published_this_run = 0
+def index_path(name):
+    name = name.lower()
+    if len(name) <= 2:
+        return "%d/%s" % (len(name), name)
+    if len(name) == 3:
+        return "3/%s/%s" % (name[0], name)
+    return "%s/%s/%s" % (name[:2], name[2:4], name)
+class Handler(http.server.BaseHTTPRequestHandler):
+    def reply(self, status, body=b"", content_type="application/json"):
+        self.send_response(status)
+        self.send_header("Content-Type", content_type)
+        self.send_header("Content-Length", str(len(body)))
+        self.end_headers()
+        self.wfile.write(body)
+    def error(self, status, detail):
+        self.reply(status, json.dumps({"errors": [{"detail": detail}]}).encode())
+    def do_GET(self):
+        if self.path == "/index/config.json":
+            base = "http://127.0.0.1:%d" % port
+            self.reply(200, json.dumps({"dl": base + "/api/v1/crates/{crate}/{version}/download", "api": base}).encode())
+            return
+        match = re.fullmatch(r"/api/v1/crates/([^/]+)/([^/]+)/download", self.path)
+        if match:
+            path = os.path.join(root, "crates", "%s-%s.crate" % match.groups())
+            self.reply(200, open(path, "rb").read(), "application/octet-stream") if os.path.exists(path) else self.error(404, "no such crate")
+            return
+        if self.path.startswith("/index/"):
+            wanted = self.path[len("/index/"):]
+            with lock:
+                lines = [e["line"] for e in state["entries"] if index_path(e["name"]) == wanted and e["visible_at"] <= time.time()]
+            if lines:
+                self.reply(200, ("\n".join(lines) + "\n").encode(), "text/plain")
+                return
+        self.error(404, "not found")
+    def do_PUT(self):
+        global published_this_run
+        if self.path != "/api/v1/crates/new":
+            self.error(404, "not found")
+            return
+        body = self.rfile.read(int(self.headers["Content-Length"]))
+        size = int.from_bytes(body[:4], "little")
+        meta = json.loads(body[4:4 + size])
+        crate_size = int.from_bytes(body[4 + size:8 + size], "little")
+        crate = body[8 + size:8 + size + crate_size]
+        with lock:
+            if published_this_run >= refuse_after:
+                self.error(403, "publish refused by the test registry")
+                return
+            if any(e["name"] == meta["name"] and e["vers"] == meta["vers"] for e in state["entries"]):
+                self.error(400, "crate version `%s` is already uploaded" % meta["vers"])
+                return
+            open(os.path.join(root, "crates", "%s-%s.crate" % (meta["name"], meta["vers"])), "wb").write(crate)
+            deps = [{"name": d["name"], "req": d["version_req"], "features": d["features"], "optional": d["optional"],
+                     "default_features": d["default_features"], "target": d["target"], "kind": d["kind"],
+                     "registry": d.get("registry"), "package": d.get("explicit_name_in_toml")} for d in meta["deps"]]
+            line = json.dumps({"name": meta["name"], "vers": meta["vers"], "deps": deps, "features": meta["features"],
+                               "cksum": hashlib.sha256(crate).hexdigest(), "yanked": False, "v": 1})
+            state["entries"].append({"name": meta["name"], "vers": meta["vers"], "line": line, "visible_at": time.time() + index_delay})
+            json.dump(state, open(state_path, "w"))
+            published_this_run += 1
+        self.reply(200, json.dumps({"warnings": {"invalid_categories": [], "invalid_badges": [], "other": []}}).encode())
+    def log_message(self, format, *args):
+        sys.stderr.write(format % args + "\n")
+        sys.stderr.flush()
+http.server.ThreadingHTTPServer(("127.0.0.1", port), Handler).serve_forever()
+"#;
+
+/// Starts [`SPARSE_CARGO_REGISTRY`] on `port`; `registry_dir` holds its crates and state across restarts.
+pub fn start_sparse_cargo_registry(
+    external: &Path,
+    name: &str,
+    port: u16,
+    registry_dir: &Path,
+    refuse_after: u32,
+    index_delay: Duration,
+) -> ServerGuard {
+    fs::create_dir_all(registry_dir).unwrap();
+    let script = external.join(format!("sparse-cargo-registry-{name}.py"));
+    fs::write(&script, SPARSE_CARGO_REGISTRY).unwrap();
+    let mut command = Command::new("python3");
+    command
+        .arg(&script)
+        .arg(registry_dir)
+        .arg(port.to_string())
+        .arg(refuse_after.to_string())
+        .arg(index_delay.as_secs_f64().to_string());
+    let log_path = log_to_file(&mut command, external, &format!("sparse-cargo-registry-{name}.log"));
+    let child = command.spawn().expect("python3 must be spawnable");
+    let mut guard = ServerGuard { child, log_path };
+    wait_for_port(&mut guard, port, Duration::from_secs(20));
+    guard
+}
+
 /// Starts a real local `cargo-http-registry` on an ephemeral loopback port,
 /// serving `registry_root` as its git-protocol index and package store; no
 /// authentication is enforced (any registry token is accepted).
diff --git a/crates/callisto-cli/tests/release_verify_real.rs b/crates/callisto-cli/tests/release_verify_real.rs
index f521de484..a667ada05 100644
--- a/crates/callisto-cli/tests/release_verify_real.rs
+++ b/crates/callisto-cli/tests/release_verify_real.rs
@@ -523,3 +523,216 @@ fn a_python_release_with_a_missing_wheel_uploads_only_the_wheel() {
         "the sdist the index already held must not be uploaded again"
     );
 }
+
+// --------------------------------------------------------------------- cargo
+
+const CARGO_ORIGIN: &str = "https://github.com/example/cargo-registry-fixture.git";
+const CARGO_REGISTRY: &str = "verify-reg";
+const CARGO_CRATES: [&str; 2] = ["callisto-verify-crate-a", "callisto-verify-crate-b"];
+
+/// A released two-crate workspace publishing to the `verify-reg` Cargo registry, whose URL only `CARGO_HOME` knows.
+struct CargoRelease {
+    release: Release,
+    port: u16,
+    registry_dir: PathBuf,
+}
+
+impl CargoRelease {
+    fn new() -> Self {
+        let external = tempfile::tempdir().unwrap();
+        let tls = Tls::generate(external.path());
+        let port = free_loopback_port();
+        let fixture = cargo_release_fixture(&format!(
+            "\n[registries.{CARGO_REGISTRY}]\nkind = \"cargo\"\nconfirm-timeout = \"30s\"\n"
+        ));
+        let cargo_home = external.path().join("cargo-home");
+        fs::create_dir_all(&cargo_home).unwrap();
+        fs::write(
+            cargo_home.join("config.toml"),
+            format!("[registries.{CARGO_REGISTRY}]\nindex = \"sparse+http://127.0.0.1:{port}/index/\"\n"),
+        )
+        .unwrap();
+        let registry_dir = external.path().join("cargo-registry");
+        let mut release = Release::new(fixture, external, tls, CARGO_ORIGIN, &format!("{}@0.2.0", CARGO_CRATES[0]));
+        release
+            .rig
+            .set("CARGO_HOME", cargo_home.to_str().unwrap())
+            .set("CARGO_REGISTRIES_VERIFY_REG_TOKEN", "callisto-verify-token")
+            // `cargo publish` must not wait for the index itself, so callisto's own confirmation is what waits.
+            .set("CARGO_PUBLISH_TIMEOUT", "0")
+            .set("__CALLISTO_TEST_SLEEP_SCALE", "0.1");
+        Self { release, port, registry_dir }
+    }
+
+    fn registry(&self, refuse_after: u32, index_delay: Duration) -> ServerGuard {
+        start_sparse_cargo_registry(
+            self.release.external.path(),
+            "cargo",
+            self.port,
+            &self.registry_dir,
+            refuse_after,
+            index_delay,
+        )
+    }
+
+    /// The crate files the registry holds.
+    fn crates(&self) -> Vec<String> {
+        files_in(&self.registry_dir.join("crates"))
+    }
+}
+
+/// A released workspace of two independent crates with a committed `Cargo.lock`.
+fn cargo_release_fixture(registries: &str) -> (tempfile::TempDir, String) {
+    let dir = tempfile::tempdir().unwrap();
+    let root = dir.path();
+    callisto_fixtures::git::init_repo(root);
+    git(root, &["remote", "add", "origin", CARGO_ORIGIN]);
+    fs::write(
+        root.join("Cargo.toml"),
+        "[workspace]\nmembers = [\"crates/*\"]\nresolver = \"2\"\n",
+    )
+    .unwrap();
+    fs::write(root.join(".gitignore"), "/target/\n").unwrap();
+    for name in CARGO_CRATES {
+        let crate_dir = root.join("crates").join(name);
+        fs::create_dir_all(crate_dir.join("src")).unwrap();
+        fs::write(
+            crate_dir.join("Cargo.toml"),
+            format!(
+                "[package]\nname = \"{name}\"\nversion = \"0.1.0\"\nedition = \"2021\"\n\
+                 description = \"verify-real probe\"\nlicense = \"MIT\"\n"
+            ),
+        )
+        .unwrap();
+        fs::write(crate_dir.join("src/lib.rs"), "pub fn probe() {}\n").unwrap();
+    }
+    let lock = std::process::Command::new("cargo")
+        .args(["generate-lockfile", "--offline"])
+        .current_dir(root)
+        .output()
+        .expect("cargo must be runnable");
+    assert!(
+        lock.status.success(),
+        "lockfile failed: {}",
+        String::from_utf8_lossy(&lock.stderr)
+    );
+    git(root, &["add", "."]);
+    git(root, &["commit", "-m", "initial workspace"]);
+
+    let init = callisto(root, &["init", "--yes", "--versioning", "independent"]);
+    assert!(init.status.success(), "init failed: {}", stderr_of(&init));
+    let config_path = root.join("callisto.toml");
+    let mut config = fs::read_to_string(&config_path).unwrap();
+    for name in CARGO_CRATES {
+        config.push_str(&format!(
+            "\n[[package]]\nmatch = \"cargo/{name}\"\npublish-to = [\"{CARGO_REGISTRY}\"]\n"
+        ));
+    }
+    config.push_str(registries);
+    fs::write(&config_path, config).unwrap();
+    git(root, &["add", "."]);
+    git(root, &["commit", "-m", "configure callisto"]);
+
+    let mut add_args = vec!["add".to_owned()];
+    for name in CARGO_CRATES {
+        add_args.extend(["--package".to_owned(), format!("cargo/{name}:minor")]);
+    }
+    add_args.extend(["--summary".to_owned(), "Ship the verify-real probes".to_owned()]);
+    let add_args: Vec<&str> = add_args.iter().map(String::as_str).collect();
+    let add = callisto(root, &add_args);
+    assert!(add.status.success(), "add failed: {}", stderr_of(&add));
+    git(root, &["add", "."]);
+    git(root, &["commit", "-m", "add release changeset"]);
+
+    let version = callisto(root, &["version", "--emit-decision", DECISION_PATH]);
+    assert!(version.status.success(), "version failed: {}", stderr_of(&version));
+    git(root, &["add", "-A"]);
+    git(root, &["commit", "-m", "release the probes 0.2.0"]);
+    let release_commit = git(root, &["rev-parse", "HEAD"]);
+    git(root, &["checkout", "--detach", &release_commit]);
+    (dir, release_commit)
+}
+
+#[test]
+#[ignore = "needs local registries; run via `just verify-real`"]
+fn a_partial_cargo_publish_is_adopted_by_the_rerun_without_republishing() {
+    let cargo = CargoRelease::new();
+    let release = &cargo.release;
+
+    let first_published = {
+        // The registry takes one crate, then refuses: the run dies between the two publishes.
+        let _registry = cargo.registry(1, Duration::ZERO);
+        let output = release.execute();
+        assert!(
+            !output.status.success(),
+            "the registry refuses the second crate, so the run must fail\n{}",
+            release.failure_context(&output)
+        );
+        assert!(!release.receipt.exists(), "a failed run must leave no terminal receipt");
+        let published = cargo.crates();
+        assert_eq!(published.len(), 1, "exactly one crate published before the failure: {published:?}");
+        published
+    };
+
+    let _registry = cargo.registry(u32::MAX, Duration::ZERO);
+    let second = release.execute();
+    release.assert_completed(&second);
+    assert!(
+        stderr_of(&second).contains("already published"),
+        "the rerun must adopt the first crate instead of publishing it again:\n{}",
+        stderr_of(&second)
+    );
+    let all = cargo.crates();
+    assert_eq!(all.len(), 2, "both crates must be on the registry: {all:?}");
+    assert!(all.contains(&first_published[0]));
+    for name in CARGO_CRATES {
+        assert!(
+            release.remote_has_tag(&format!("{name}@0.2.0")),
+            "{name} tag must reach the remote"
+        );
+    }
+}
+
+#[test]
+#[ignore = "needs local registries; run via `just verify-real`"]
+fn a_cargo_release_waits_for_a_delayed_index() {
+    let cargo = CargoRelease::new();
+    let release = &cargo.release;
+    let registry = cargo.registry(u32::MAX, Duration::from_millis(2500));
+
+    let started = Instant::now();
+    let output = release.execute();
+    release.assert_completed(&output);
+    assert!(
+        started.elapsed() > Duration::from_millis(2500) && registry.log().contains("\" 404 "),
+        "the run must have looked at the index while it was empty:\n{}",
+        registry.log()
+    );
+    assert_eq!(cargo.crates().len(), 2);
+}
+
+#[test]
+#[ignore = "needs local registries; run via `just verify-real`"]
+fn a_cargo_remote_tag_on_another_commit_stops_the_release_with_a_conflict() {
+    let cargo = CargoRelease::new();
+    let release = &cargo.release;
+    let _registry = cargo.registry(u32::MAX, Duration::ZERO);
+    let other = git(release.root(), &["rev-parse", "HEAD~1"]);
+    let tag = format!("{}@0.2.0", CARGO_CRATES[1]);
+    git(
+        release.root(),
+        &[
+            "push",
+            &format!("file://{}", release.bare.display()),
+            &format!("{other}:refs/tags/{tag}"),
+        ],
+    );
+
+    let output = release.execute();
+    release.assert_failed_with(&output, "E167");
+    assert_eq!(
+        git(&release.bare, &["rev-parse", &format!("refs/tags/{tag}^{{commit}}")]),
+        other,
+        "the foreign tag must be left as it was"
+    );
+}
diff --git a/docs/architecture/release.md b/docs/architecture/release.md
index 764025d44..dc1d9ba68 100644
--- a/docs/architecture/release.md
+++ b/docs/architecture/release.md
@@ -141,4 +141,14 @@ Downloaded binaries are checked with `gh attestation verify` against `orin-dx/ca

 Product assets target `aarch64-apple-darwin`, `x86_64-apple-darwin`, `x86_64-unknown-linux-gnu`, `aarch64-unknown-linux-gnu`, and `x86_64-unknown-linux-musl`. The Intel macOS asset is cross-compiled on an Apple silicon runner, and the arm64 Linux asset is built natively on an arm64 runner. Apple signing and notarization are out of scope. GitHub provenance binds assets to the orchestration revision; the intent and artifact manifest bind their bytes to the release source. Callisto publishes its crates to crates.io and product assets to GitHub Releases, not to another registry for rehearsal.

-`just verify-real` rehearses recovery against local registries through the production registry binding, with no test-only allowance in the https rule: Verdaccio, `pypiserver` and a JSON simple index serve a self-signed loopback certificate that npm, curl and Twine trust through their own CA variables. The rehearsals are a partial npm publish adopted by a rerun, a PyPI index that shows an upload late or never, a remote tag on another commit, and a PyPI release whose index lacks one built file. Cargo is not rehearsed: its publish and observation always name the `crates-io` registry, which cannot be pointed at a local one.
+`just verify-real` rehearses recovery against local registries through the production registry binding, with no test-only allowance in the https rule: Verdaccio, `pypiserver` and a JSON simple index serve a self-signed loopback certificate that npm, curl and Twine trust through their own CA variables. The rehearsals are a partial npm publish adopted by a rerun, a PyPI index that shows an upload late or never, a remote tag on another commit, and a PyPI release whose index lacks one built file. Cargo is rehearsed through a `kind = "cargo"` registry named in `publish-to`: a local sparse registry with the publish and download API stands behind `[registries.<name>] index` in a scratch `CARGO_HOME`, and callisto passes `--registry <name>` to `cargo publish` and `cargo info`. The Cargo rehearsals are a partial publish adopted by a rerun, an index that shows a publish late, and a remote tag on another commit. A `crates-io` publish runs plain `cargo publish`, so it is not rehearsed against a local registry.
+
+`just verify-real` then runs `native_resolution_e2e_tests` and fails when `npm`, `pnpm` or `uv` is missing, so the matrix is recorded rather than skipped. After `version` or `snapshot` each ecosystem's own locked install must still succeed:
+
+| Ecosystem | Command | Checked after |
+| --- | --- | --- |
+| Cargo | `cargo metadata --locked --offline` | `version`, `snapshot` |
+| npm | `npm ci` | `version`, `snapshot` |
+| pnpm | `pnpm install --frozen-lockfile` | `version`, `snapshot`, lockfile refresh |
+| pnpm | `pnpm pack` with `workspace:` protocols rewritten to the released versions | `version`, `snapshot` |
+| Python | `uv lock --check` | `version`, `snapshot` |
